/**
 * Action executor function signature.
 * The execute function receives all context needed for orchestration.
 */
export type ActionExecutor<TInput = any> = (
  params: ActionExecutorParams<TInput>
) => Promise<any>;

/**
 * Custom error class for action handlers.
 * Thrown errors are caught by the action route and returned as JSON responses.
 *
 * @example
 * throw new ActionError('Not enough balance', 'INSUFFICIENT_FUNDS', 400, {
 *   required: 100,
 *   available: record.balance,
 * });
 */
export class ActionError extends Error {
  readonly code: string;
  readonly statusCode: number;
  readonly details?: Record<string, any>;

  constructor(
    message: string,
    code: string,
    statusCode: number = 400,
    details?: Record<string, any>
  ) {
    super(message);
    this.name = 'ActionError';
    this.code = code;
    this.statusCode = statusCode;
    this.details = details;
  }
}

/**
 * Thrown by record-action handlers when the canonical state UPDATE returned
 * zero rows because the row's transition field changed between the route's
 * pre-check and the UPDATE itself. The action route catches this and
 * translates to 409 ACCESS_TRANSITION_LOST — distinct from ActionError so
 * handlers don't need to remember the right code.
 *
 * @example
 *   const [updated] = await db.update(applications)
 *     .set({ status: 'hired' })
 *     .where(whereTransition!(applications))
 *     .returning();
 *   if (!updated) throw new TransitionLostError('status', 'offer', 'hired');
 */
export class TransitionLostError extends Error {
  readonly field: string;
  readonly expectedFrom: string;
  readonly attemptedTo: string;

  constructor(field: string, expectedFrom: string, attemptedTo: string) {
    super(`Transition lost: ${field} was no longer ${expectedFrom} when the update fired (target: ${attemptedTo})`);
    this.name = 'TransitionLostError';
    this.field = field;
    this.expectedFrom = expectedFrom;
    this.attemptedTo = attemptedTo;
  }
}

// ── Realtime registry define* (Part A) ────────────────────────────────────
// Runtime homes for the compile-time realtime define helpers. The copied
// `src/services/realtime/*.ts` registry modules import these from here (the
// compiler rewrites `@quickback/{types,compiler}` → `lib/types`), so they must
// exist as real, self-contained runtime values + types with no `@quickback/*`
// dependency. Payload / input schema fields stay loosely typed (`unknown`) —
// the generated runtime only passes them through; Zod validation is a later
// slice. Kept in lockstep with `apps/compiler/src/define/realtime.ts`.

export interface RealtimeEventVariant {
  reason: string;
  payload: unknown;
}
export interface RealtimeTypedEvent {
  wireName: string;
  version: number;
  variants: Record<string, RealtimeEventVariant>;
  deliveries: string[];
  description?: string;
}
export interface RealtimeDefinition {
  name: string;
  events: string[] | Record<string, RealtimeTypedEvent>;
  description?: string;
}
export interface RealtimeRecipientsConfig {
  input: unknown;
  resolve: (...args: any[]) => unknown;
}
export interface RealtimeDeliveryConfig {
  target:
    | { scopeKeyFrom: string; organizationId?: never; userIdFrom?: never }
    | { organizationId: string; userIdFrom: string; scopeKeyFrom?: never };
  access: { roles: string[] };
  recipients?: RealtimeRecipientsConfig;
  description?: string;
}

const REALTIME_IDENT = /^[a-zA-Z_][a-zA-Z0-9_]*$/;
const RESERVED_REALTIME_KEYS = new Set(['name', 'events', 'description']);

function isTypedRealtimeEvents(
  events: RealtimeDefinition['events'],
): events is Record<string, RealtimeTypedEvent> {
  return !Array.isArray(events);
}

function validateTypedRealtimeEvent(namespace: string, key: string, ev: RealtimeTypedEvent): void {
  const where = `defineRealtime("${namespace}").events.${key}`;
  if (!REALTIME_IDENT.test(key)) {
    throw new Error(`${where}: event key "${key}" must be a valid identifier (camelCase).`);
  }
  if (!ev || typeof ev !== 'object') {
    throw new Error(`${where}: must be an object with { wireName, version, variants, deliveries }.`);
  }
  if (typeof ev.wireName !== 'string' || ev.wireName.length === 0) {
    throw new Error(`${where}.wireName: required non-empty wire literal.`);
  }
  if (typeof ev.version !== 'number' || !Number.isInteger(ev.version) || ev.version < 1) {
    throw new Error(`${where}.version: required positive integer.`);
  }
  if (!ev.variants || typeof ev.variants !== 'object' || Object.keys(ev.variants).length === 0) {
    throw new Error(`${where}.variants: at least one variant is required.`);
  }
  for (const [vk, variant] of Object.entries(ev.variants)) {
    if (!REALTIME_IDENT.test(vk)) {
      throw new Error(`${where}.variants.${vk}: variant key must be a valid identifier.`);
    }
    if (!variant || typeof variant.reason !== 'string' || variant.reason.length === 0) {
      throw new Error(`${where}.variants.${vk}.reason: required non-empty wire literal.`);
    }
    if (variant.payload == null || typeof variant.payload !== 'object') {
      throw new Error(`${where}.variants.${vk}.payload: required strict schema object.`);
    }
  }
  if (!Array.isArray(ev.deliveries) || ev.deliveries.length === 0) {
    throw new Error(`${where}.deliveries: at least one delivery-profile name is required.`);
  }
}

/**
 * Define a custom realtime event namespace, or a typed named-invalidation
 * registry. Passthrough for type safety; typed event keys are hoisted onto the
 * returned object so `registry.<eventKey>` is both a valid property access and
 * a real runtime value (the symbol-ref `invalidates` form needs both).
 */
export function defineRealtime<const D extends RealtimeDefinition>(
  definition: D,
): D & (D['events'] extends Record<string, RealtimeTypedEvent> ? D['events'] : {}) {
  if (!definition.name) {
    throw new Error('Realtime definition requires a name');
  }
  if (!definition.events) {
    throw new Error('Realtime definition requires at least one event');
  }
  if (isTypedRealtimeEvents(definition.events)) {
    if (Object.keys(definition.events).length === 0) {
      throw new Error('Realtime definition requires at least one event');
    }
    for (const [key, ev] of Object.entries(definition.events)) {
      if (RESERVED_REALTIME_KEYS.has(key)) {
        throw new Error(
          `defineRealtime("${definition.name}"): event key "${key}" is reserved — it collides with a top-level definition field (name/events/description). Rename the event.`,
        );
      }
      validateTypedRealtimeEvent(definition.name, key, ev);
    }
  } else {
    if (definition.events.length === 0) {
      throw new Error('Realtime definition requires at least one event');
    }
    for (const event of definition.events) {
      if (!REALTIME_IDENT.test(event)) {
        throw new Error(`Invalid event name: "${event}". Must be a valid JavaScript identifier.`);
      }
    }
  }
  const hoist = isTypedRealtimeEvents(definition.events) ? definition.events : {};
  return { ...definition, ...hoist } as any;
}

/** Define a named delivery profile — the MAXIMUM audience for a named invalidation. */
export function defineRealtimeDelivery(config: RealtimeDeliveryConfig): RealtimeDeliveryConfig {
  const t = config?.target as Record<string, unknown> | undefined;
  const hasScope = typeof t?.scopeKeyFrom === 'string';
  const hasAccount = typeof t?.organizationId === 'string' && typeof t?.userIdFrom === 'string';
  if (!hasScope && !hasAccount) {
    throw new Error('defineRealtimeDelivery: target must be either { scopeKeyFrom } or { organizationId, userIdFrom }.');
  }
  if (hasScope && (t?.organizationId !== undefined || t?.userIdFrom !== undefined)) {
    throw new Error('defineRealtimeDelivery: target cannot mix scopeKeyFrom with the account lane.');
  }
  if (!config.access || !Array.isArray(config.access.roles) || config.access.roles.length === 0) {
    throw new Error('defineRealtimeDelivery: access.roles is required and non-empty — a delivery profile is the max audience, so WHO is not optional (fail-closed).');
  }
  return config;
}

/** Define a scoped recipient resolver (Slice 2) — post-commit identity resolution. */
export function defineRealtimeRecipients(config: RealtimeRecipientsConfig): RealtimeRecipientsConfig {
  if (config?.input == null || typeof config.input !== 'object') {
    throw new Error('defineRealtimeRecipients: input must be a strict schema object.');
  }
  if (typeof config.resolve !== 'function') {
    throw new Error('defineRealtimeRecipients: resolve must be a function ({ db, input, recipient }) => Identity[].');
  }
  return config;
}

